        TransactionService service = new TransactionService();

        // Create transactions
        List<Transaction> transactions = Arrays.asList(
            new Transaction(1, 101, 100.0, TransactionStatus.COMPLETED),
            new Transaction(2, 102, -50.0, TransactionStatus.PENDING),
