            service.processTransaction(transaction);
        }

        // Get customer summaries
        List<Map.Entry<Integer, Double>> customerSummaries = service.getCustomerSummaries();

        // Print customer summaries
        for (Map.Entry<Integer, Double> entry : customerSummaries) {
            System.out.println("Customer ID: " + entry.getKey() + ", Total Revenue: " + entry.getValue());
        }
    }
}
